// [weightThreshold, basePower] — source walks this in order and takes the
// FIRST row whose threshold EXCEEDS the target's weight (Cmd_weightdamage-
// calculation, :9467-9482); falling off the end is 120.
const WEIGHT_TO_DAMAGE = [[100,20],[250,40],[500,60],[1000,80],[2000,100]];

export function lowKickPower(speciesName) {
  const w = SPECIES_WEIGHT[speciesName];
  if (w === undefined) {
    throw new Error(`lowKickPower: no dex weight for "${speciesName}" — regenerate species-weights.js`);
  }
  for (const [threshold, power] of WEIGHT_TO_DAMAGE) if (threshold > w) return power;
  return 120;
}
